def count_islands(spec: dict) -> int:
    """Number of connected components in the undirected graph."""
    adj = {n: [] for n in spec["nodes"]}
    for a, b in spec["links"]:
        adj[a].append(b)
        adj[b].append(a)
    seen = set(); islands = 0
    for n in spec["nodes"]:
        if n in seen:
            continue
        islands += 1
        stack = [n]
        while stack:
            cur = stack.pop()
            if cur in seen:
                continue
            seen.add(cur)
            stack.extend(adj[cur])
    return islands
```

