def follower_reach(spec: dict) -> list:
    """Users reachable within two Follow hops of the target, sorted, excluding the target."""
    users = set(spec["users"])
    who = spec["who"]
    if who not in users:
        return []
    adj = {}
    for f in spec["follows"]:
        if f[0] in users and f[1] in users:
            adj.setdefault(f[0], set()).add(f[1])
    one = adj.get(who, set())
    reach = set(one)
    for u in one:
        reach |= adj.get(u, set())
    reach.discard(who)
    return sorted(reach)
